<tr data-sales-line><td><input type="hidden" name="lines[<?=h($i)?>][id]" value="<?=h($l['id']??0)?>"><select class="form-select" aria-label="Artigo" data-search-placeholder="Pesquisar pela descrição ou código do artigo…" name="lines[<?=h($i)?>][finished_product_id]" required><option value="">Selecione…</option><?php foreach($articles as $a):if($a['status']!=='Ativo'&&$a['id']!=($l['finished_product_id']??0))continue;?><option value="<?=(int)$a['id']?>" data-customer="<?=(int)$a['customer_id']?>" data-description="<?=h($a['description'])?>" <?=$a['id']==($l['finished_product_id']??0)?'selected':''?>><?=h($a['code'].' — '.$a['description'])?></option><?php endforeach;?></select></td><?php foreach(['description'=>'text','quantity'=>'number','unit_price'=>'number','discount_percent'=>'number','expected_date'=>'date'] as $key=>$type):?><td><input class="form-control" aria-label="<?=h(['description'=>'Descrição','quantity'=>'Quantidade','unit_price'=>'Preço unitário','discount_percent'=>'Desconto','expected_date'=>'Entrega prevista'][$key])?>" name="lines[<?=h($i)?>][<?=$key?>]" type="<?=$type?>" <?=$type==='number'?'step="0.0001" min="0"':''?> <?=$key==='quantity'?'required':''?> value="<?=h(SalesOrderService::text($l,$key))?>"></td><?php endforeach;?><td><div class="sales-line-actions"><?php if(empty($l['id'])):?><button class="btn btn-sm btn-outline-secondary" type="button" data-remove-sales-line aria-label="Remover linha nova">×</button><?php else:?><span class="small text-secondary">#<?=(int)$l['line_number']?></span><?php endif;?><button class="btn btn-sm btn-outline-primary" type="button" data-add-sales-line aria-label="Adicionar artigo" title="Adicionar artigo"><i class="bi bi-plus-lg" aria-hidden="true"></i></button></div></td></tr>
